"""
Analyze aggregated end-to-end (Playwright) test results and build a Slack report.

Consumes the ``failures.json`` / ``fixme_tests.json`` summaries produced by
``extract_e2e_test_results.py`` across several CI runs and browsers, identifies
tests that fail often enough to be worth marking with ``fixme``, and formats a
Slack Block Kit message summarising the state of the end-to-end suite.
"""

from __future__ import annotations

import json
import os
from pathlib import Path

# Slack channel the report is posted to.
SLACK_CHANNEL = "airflow-3-ui"

# A test must fail in at least this fraction of the runs (with data) before it is
# considered a flaky candidate worth marking with ``fixme``. This keeps rare,
# one-off failures (e.g. a single failure across many runs) out of the report.
MIN_FAILURE_RATE = 0.2


def escape_slack_mrkdwn(text: str) -> str:
    """Escape the characters that are special in Slack ``mrkdwn`` text.

    Replaces ``&`` with ``&amp;``, ``<`` with ``&lt;`` and ``>`` with ``&gt;``.
    ``&`` must be escaped first so the entities added for ``<`` / ``>`` are not
    escaped again. Text without any special characters is returned unchanged.
    """
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def _failure_count(info) -> int:
    """Best-effort extraction of the number of failures for a single test."""
    if isinstance(info, dict):
        if isinstance(info.get("count"), (int, float)):
            return int(info["count"])
        if isinstance(info.get("failure_count"), (int, float)):
            return int(info["failure_count"])
        for key in ("failures", "errors", "runs"):
            value = info.get(key)
            if isinstance(value, list):
                return len(value)
        return 0
    if isinstance(info, list):
        return len(info)
    if isinstance(info, (int, float)):
        return int(info)
    return 0


def _error_messages(info) -> list:
    """Best-effort extraction of error messages for a single test."""
    if isinstance(info, dict):
        errors = info.get("errors")
        if isinstance(errors, list):
            return [str(e) for e in errors]
        if info.get("error") is not None:
            return [str(info["error"])]
        failures = info.get("failures")
        if isinstance(failures, list):
            return [str(f.get("error", "")) if isinstance(f, dict) else str(f) for f in failures]
        return []
    if isinstance(info, list):
        return [str(f.get("error", "")) if isinstance(f, dict) else str(f) for f in info]
    return []


def identify_flaky_candidates(failures_by_test: dict, runs_with_data: int) -> list:
    """Identify tests that fail often enough to be flaky-fix candidates.

    Returns an empty list when there is no data to analyse (no failures or no
    runs). Otherwise returns a list of ``{"test", "failure_rate", ...}`` dicts for
    tests whose failure rate meets :data:`MIN_FAILURE_RATE`, sorted by
    ``failure_rate`` in descending order.
    """
    if not failures_by_test or not runs_with_data:
        return []

    candidates = []
    for test, info in failures_by_test.items():
        failure_count = _failure_count(info)
        if failure_count <= 0:
            continue
        failure_rate = failure_count / runs_with_data
        if failure_rate < MIN_FAILURE_RATE:
            continue
        candidates.append(
            {
                "test": test,
                "failure_rate": failure_rate,
                "failure_count": failure_count,
            }
        )

    candidates.sort(key=lambda candidate: candidate["failure_rate"], reverse=True)
    return candidates


